import { l, type L } from '../i18n';
import type { CareerState, EffectTarget, SkillId, StageId } from '../model/types';

/**
 * Story events. Shown at the start of each offseason and occasionally between tournaments.
 * Text supports {vars} from `vars()` and [[masculine|feminine]] markers.
 * Effect summaries are generated by the UI from `effects`, `hint` adds flavour only.
 */
export interface StoryOption {
  label: L;
  hint?: L;
  effects: EffectTarget[];
  result: L;
  /** Optional roll — success applies `effects`, failure applies `failEffects`. */
  roll?: {
    skills?: Partial<Record<SkillId, number>>;
    stat?: 'media' | 'reputation' | 'morale';
    base: number;
  };
  failEffects?: EffectTarget[];
  failResult?: L;
  /** Option is only available when the budget covers this amount. */
  cost?: number;
}

export interface StoryEvent {
  id: string;
  context: 'offseason' | 'midseason';
  stages?: StageId[];
  minAge?: number;
  maxAge?: number;
  weight: number;
  once?: boolean;
  /** At most once per season. */
  oncePerSeason?: boolean;
  /** Priority events jump the queue when their condition holds. */
  priority?: boolean;
  condition?: (s: CareerState) => boolean;
  vars?: (s: CareerState) => Record<string, string | number>;
  text: L;
  options: StoryOption[];
}

const skill = (s: SkillId, delta: number): EffectTarget => ({ kind: 'skill', skill: s, delta });
const budget = (delta: number): EffectTarget => ({ kind: 'budget', delta });
const media = (delta: number): EffectTarget => ({ kind: 'media', delta });
const rep = (delta: number): EffectTarget => ({ kind: 'reputation', delta });
const morale = (delta: number): EffectTarget => ({ kind: 'morale', delta });
const fatigue = (delta: number): EffectTarget => ({ kind: 'fatigue', delta });

const nemesisName = (s: CareerState) => {
  const n = s.field.find((ai) => ai.nemesis);
  return n ? `${n.first} ${n.last}` : '—';
};

